 ****************************************************************************/

/****************************************************************************
 * Name: task_join
 *
 * Description:
 *   Check if a thread can be joined and return appropriate error code.
 *   This function provides a centralized way to handle join-related error
 *   conditions according to POSIX standards.
 *
 * Input Parameters:
 *   pid - The ID of the thread to check
 *
 * Returned Value:
 *   EINVAL if the thread is detached or otherwise not joinable
 *   ESRCH if no thread could be found with the given ID
 *   OK if the thread can be joined
 *
 ****************************************************************************/

int task_join(pid_t pid)
{
  FAR struct tcb_s *tcb;

  /* First, check if the thread exists */

  tcb = nxsched_get_tcb(pid);
  if (tcb == NULL)
    {
      return ESRCH;
    }

  /* Check if the thread is a pthread */

  if ((tcb->flags & TCB_FLAG_TTYPE_MASK) != TCB_FLAG_TTYPE_PTHREAD)
    {
      return EINVAL;
    }

  /* Check if the thread is detached */

  if ((tcb->join_complete) != 0)
    {
      return EINVAL;
    }

  return OK;
}
